#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int N=2e6+5;
int n,r[N],f[N],g[N],h[N];
ll x[N],d,ans;
int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    int c,t;
    cin>>c>>t;
    while(t--){
        cin>>n>>d;
        for(int i=1;i<=n;i++)cin>>x[i];
        // r[i]：从 i 一步能到的最右点（双指针，单调）
        for(int i=1,j=1;i<=n;i++){
            j=max(j,i);
            while(j<n&&x[j+1]-x[i]<=d)j++;
            r[i]=j;
        }
        fill(f,f+n+2,0);
        fill(g,g+n+2,0);
        fill(h,h+n+2,0);
        for(int i=n;i>=1;i--){
            int r1=(i>=2?r[i-1]:0),r2=(i>=3?r[i-2]:0);
            int a=r[i]-max(i,r1);          // i 能到、i-1 到不了的点数
            int b=max(0,r1-max(i,r2));     // i、i-1 能到、i-2 到不了的点数
            if(a>0){
                h[i]=a+h[r[i]];
                f[i]=(a==1?f[r[i]]:g[r[i]]);
                g[i]=b+f[i];
            }else if(b>0){
                g[i]=b+h[r[i]];
            }
        }
        ans=0;
        for(int i=1;i<=n;i++){
            if(r[i]-i==1)ans+=f[r[i]];
            if(r[i]-i>=2)ans+=g[r[i]];
        }
        cout<<ans<<'\n';
    }
    return 0;
}
